function validate([parent, s]) {
  const n = parent.length;
  if (n < 1 || n > 100000) return 'parent needs 1 to 10^5 entries.';
  if (typeof s !== 'string' || s.length !== n) return 's needs exactly one letter per node.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (parent[0] !== -1) return 'parent[0] must be -1, since node 0 is the root.';
  const children = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    const above = parent[i];
    if (!Number.isInteger(above) || above < 0 || above >= n || above === i) return 'Each parent[i] for i >= 1 is another node from 0 to n - 1.';
    children[above].push(i);
  }
  const reached = [0];
  for (let k = 0; k < reached.length; k++) for (const child of children[reached[k]]) reached.push(child);
  if (reached.length !== n) return 'parent must form a single tree rooted at node 0, with no cycles.';
  return null;
}

