function findAnswer(parent, s) {
  const n = parent.length;
  const children = Array.from({ length: n }, () => []);
  for (let node = 1; node < n; node++) {
    children[parent[node]].push(node);
  }
  const letters = [];
  const start = new Array(n).fill(0);
  const end = new Array(n).fill(0);
  const nextChild = new Array(n).fill(0);
  const stack = [0];
  while (stack.length > 0) {
    const node = stack[stack.length - 1];
    if (nextChild[node] < children[node].length) {
      const child = children[node][nextChild[node]];
      nextChild[node]++;
      start[child] = letters.length;
      stack.push(child);
    } else {
      stack.pop();
      end[node] = letters.length;
      letters.push(s[node]);
    }
  }
  const padded = ['#'];
  for (const letter of letters) {
    padded.push(letter, '#');
  }
  const radius = new Array(padded.length).fill(0);
  let center = 0;
  let right = 0;
  for (let i = 0; i < padded.length; i++) {
    let arm = i < right ? Math.min(right - i, radius[2 * center - i]) : 0;
    while (i - arm > 0 && i + arm + 1 < padded.length && padded[i - arm - 1] === padded[i + arm + 1]) {
      arm++;
    }
    radius[i] = arm;
    if (i + arm > right) {
      center = i;
      right = i + arm;
    }
  }
  const answer = [];
  for (let node = 0; node < n; node++) {
    const length = end[node] - start[node] + 1;
    answer.push(radius[start[node] + end[node] + 1] >= length);
  }
  return answer;
}

