function findAnswer(parent, s) {
  // Follow the definition directly: write out each node's DFS string from scratch and compare it with its reverse.
  const n = parent.length;
  const kids = Array.from({ length: n }, () => []);
  parent.forEach((above, node) => { if (above !== -1) kids[above].push(node); });
  kids.forEach(list => list.sort((a, b) => a - b));
  const write = (x, out) => {
    for (const y of kids[x]) write(y, out);
    out.push(s[x]);
    return out;
  };
  return parent.map((_, i) => {
    const text = write(i, []).join('');
    return text === text.split('').reverse().join('');
  });
}

