function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 10);
  // Build a shape whose parents come first (path, star, binary, long and bushy, random),
  // then renumber nodes 1..n-1 at random so parent[i] can be larger than i.
  const shape = Math.floor(rand() * 5);
  const shapeParent = [-1];
  for (let i = 1; i < n; i++) {
    if (shape === 0) shapeParent.push(i - 1);
    else if (shape === 1) shapeParent.push(0);
    else if (shape === 2) shapeParent.push(Math.floor((i - 1) / 2));
    else if (shape === 3) shapeParent.push(Math.max(0, i - 1 - Math.floor(rand() * 3)));
    else shapeParent.push(Math.floor(rand() * i));
  }
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 1; i--) {
    const j = 1 + Math.floor(rand() * i);
    [label[i], label[j]] = [label[j], label[i]];
  }
  const parent = new Array(n).fill(-1);
  for (let i = 1; i < n; i++) parent[label[i]] = label[shapeParent[i]];
  // Letters are chosen along the root's post-order, so the root's DFS string can follow any pattern:
  // random, a palindrome, a palindrome with one letter changed, or a repeated palindromic block.
  const children = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) children[parent[i]].push(i);
  const order = [];
  const walk = [0];
  const entered = new Array(n).fill(0);
  while (walk.length) {
    const x = walk[walk.length - 1];
    if (entered[x] < children[x].length) walk.push(children[x][entered[x]++]);
    else order.push(walk.pop());
  }
  const alphabet = large ? [2, 3, 26][Math.floor(rand() * 3)] : 1 + Math.floor(rand() * 3);
  const pick = () => String.fromCharCode(97 + Math.floor(rand() * alphabet));
  const style = Math.floor(rand() * 4);
  let text = Array.from({ length: n }, pick);
  if (style === 1 || style === 2) for (let i = 0; i < n / 2; i++) text[n - 1 - i] = text[i];
  if (style === 2) { const k = Math.floor(rand() * n); text[k] = text[k] === 'a' ? 'b' : 'a'; }
  if (style === 3) {
    const word = [...'abc'.slice(0, 2 + Math.floor(rand() * 2))];
    const unit = [...word, ...word.slice().reverse()];
    const shift = Math.floor(rand() * unit.length);
    text = Array.from({ length: n }, (_, i) => unit[(i + shift) % unit.length]);
  }
  const letters = new Array(n);
  for (let i = 0; i < n; i++) letters[order[i]] = text[i];
  return [parent, letters.join('')];
}
